import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:url_launcher/url_launcher.dart';import '../../providers/app_state.dart';import '../../widgets/common.dart';
class EmergencyScreen extends ConsumerWidget{const EmergencyScreen({super.key});@override Widget build(BuildContext c,WidgetRef ref){final e=ref.watch(emergencyProvider);return Scaffold(appBar:AppBar(title:const Text('Emergency Profile')),body:ListView(padding:const EdgeInsets.all(16),children:[FilledButton.icon(style:FilledButton.styleFrom(backgroundColor:Colors.red,minimumSize:const Size.fromHeight(72)),onPressed:()=>launchUrl(Uri.parse('tel:${e.contactPhone.isEmpty?'911':e.contactPhone}')),icon:const Icon(Icons.call),label:const Text('CALL SOS')),Card(child:Column(children:[ListTile(title:const Text('Contact'),subtitle:Text('${e.contactName} • ${e.contactPhone}')),ListTile(title:const Text('Blood group'),subtitle:Text(e.bloodGroup)),ListTile(title:const Text('Allergies'),subtitle:Text(e.allergies.isEmpty?'Not provided':e.allergies)),ListTile(title:const Text('Conditions'),subtitle:Text(e.conditions.isEmpty?'Not provided':e.conditions)),ListTile(title:const Text('Current medications'),subtitle:Text(e.medications.isEmpty?'Not provided':e.medications))])),const DisclaimerCard()]));}}
